units.content:
// Transport-free CodeTour creation rules.
//
// A caller supplies the workspace to create in and the proposal it received;
// the entry points validate, apply the Git, image, Mermaid and
// workspace-confinement rules, write the Tour file atomically, and return the
// outcome as a value. The command-line surface is the only consumer, so the
// rules live here once instead of in each surface.

export { createChangesTour, createProjectTour } from "./creation";
export {
  CREATIONS_DIRECTORY,
  CREATION_RECORD_VERSION,
  creationIdentity,
  recordCreation,
} from "./journal";
export type { CreationIdentity, CreationRecord, CreationRecordInput } from "./journal";
export { createContext, selectContext } from "./context";
export {
  changedFiles,
  committedDiffIsEmpty,
  currentBranchName,
  currentHeadSha,
  git,
  isGitRepository,
  mergeBase,
  normalizeSlashes,
  readCommitAnchors,
  renamedFiles,
  resolveCommit,
  uncommittedChanges,
  workspacePrefix,
} from "./git";
export type { CommitAnchor, GitResult, UncommittedEntry } from "./git";
export { validateCodetourTour } from "./codetour-schema";
export { OutputPathError, writeTourAtomic } from "./persistence";
export { stageCommitAnchors, validateTourProposal } from "./proposal-validation";
export type {
  CommitComparison,
  ProposalRejection,
  ProposalValidation,
  StagedCommitAnchors,
  TourProposalKind,
  ValidatedProposal,
} from "./proposal-validation";
export { IMAGE_TOOL_GUIDANCE, tourImageDirectoryName, validateImageDescriptions } from "./image-validation";
export { MERMAID_TOOL_GUIDANCE, validateMermaidDescriptions } from "./mermaid-validation";
export {
  MAX_PATTERN_LENGTH,
  MAX_QUESTIONS,
  MAX_RECOMMENDED_DIAGRAM_NODES,
  MAX_RECOMMENDED_STEPS,
  orientationStepWarnings,
  STEP_FIELDS,
  validateChangesParams,
  validateProjectParams,
  validateSteps,
} from "./validation";
export type { AnchorSource } from "./validation";
export * from "./types";

export interface Position {
  line: number;
  character: number;
}

export interface Selection {
  start: Position;
  end: Position;
}

export interface TourStep {
  title?: string;
  description: string;
  questions?: string[];
  file?: string;
  baseFile?: string;
  display?: "diff";
  directory?: string;
  line?: number;
  pattern?: string;
  selection?: Selection;
}

export interface ProjectParams {
  workspacePath?: string;
  title?: string;
  description?: string;
  fileName?: string;
  steps?: unknown[];
}

export type ReviewMode = "neutral" | "critical";

export interface ChangesParams extends ProjectParams {
  baseRef?: string;
  headRef?: string;
  includeUncommittedChanges?: boolean;
  reviewMode?: ReviewMode;
}

export interface TourFile {
  $schema?: string;
  title: string;
  description?: string;
  ref?: string;
  baseRef?: string;
  steps: TourStep[];
}

export interface Issue {
  path: string;
  message: string;
}

export interface Warning {
  code: string;
  message: string;
}

export interface WorkspaceContext {
  root: string;
  realRoot: string;
}

/** The two Tour kinds the creation rules can produce. */
export type TourKind = "project" | "changes";

/** A Tour that exists on disk, as the creation rules report it. */
export interface CreatedTour {
  kind: TourKind;
  /** Canonical workspace root the creation was requested for. */
  workspaceRoot: string;
  /** Absolute path of the written Tour file. */
  tourPath: string;
  title: string;
  stepCount: number;
  warnings: Warning[];
}

/** A refused creation: nothing was written and no existing Tour was touched. */
export interface CreationFailure {
  ok: false;
  code: string;
  message: string;
  issues?: Issue[];
}

export type CreationResult = (CreatedTour & { ok: true }) | CreationFailure;

export interface CreateTourOptions {
  /** Workspace the creation runs in; every anchor and output stays inside it. */
  workspaceRoot: string;
  /** The proposal, exactly as the caller received it: untrusted JSON. */
  proposal: unknown;
  /**
   * Name of the entry point the report addresses, so a rejection names the
   * command the caller actually ran. Without one, the entry point is named
   * after the Tour kind: `create-project-tour` or `create-changes-tour`.
   */
  surface?: string;
}

import { randomBytes } from "crypto";
import { promises as fs } from "fs";
import * as path from "path";
import { TourKind } from "./types";

// Creation journal: one record per created Tour, under
// `<workspace>/.tours/.log/creations/`. The hook surfaces of the agents read
// it to report the Tours a response actually created; the record therefore
// carries the creation time and whatever session identity the creating
// process could observe, and nothing else.
//
// It is observability only. A record is an independent file, written
// atomically after the Tour exists, so concurrent creations never contend for
// one document; a journal that cannot be written never fails the creation and
// is never reported as one.

/** Directory of the creation records, relative to the workspace root. */
export const CREATIONS_DIRECTORY = path.join(".tours", ".log", "creations");

export const CREATION_RECORD_VERSION = 1;

export interface CreationRecord {
  version: number;
  /** Canonical workspace root the creation was requested for. */
  workspace: string;
  /** Absolute path of the written Tour file. */
  tourPath: string;
  tourTitle: string;
  kind: TourKind;
  /** ISO timestamp of the successful write. */
  at: string;
  sessionId: string | null;
  responseId: string | null;
  host: string | null;
}

export interface CreationIdentity {
  sessionId: string | null;
  responseId: string | null;
  host: string | null;
}

function nonEmpty(value: string | undefined): string | null {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return trimmed === "" ? null : trimmed;
}

// The identity is read from the environment of the creating process only: a
// value CodeTour cannot observe stays null instead of being guessed. The
// explicit variables name the session, the response and the host; a host that
// exports its own session variable is used when it identifies the host, which
// is why its presence also states the host name. Both host variables were
// verified on the installed CLIs: Pi exports PI_SESSION_ID to the bash tool,
// and the Copilot CLI exports COPILOT_AGENT_SESSION_ID, whose value equals the
// `sessionId` its agentStop hook receives.
export function creationIdentity(
  env: Record<string, string | undefined> = process.env
): CreationIdentity {
  const explicitSession = nonEmpty(env.CODETOUR_SESSION_ID);
  const piSession = nonEmpty(env.PI_SESSION_ID);
  const copilotSession = nonEmpty(env.COPILOT_AGENT_SESSION_ID);
  const [sessionId, observedHost]: [string | null, string | null] =
    explicitSession !== null ? [explicitSession, null]
      : piSession !== null ? [piSession, "pi"]
        : copilotSession !== null ? [copilotSession, "copilot"]
          : [null, null];
  return {
    sessionId,
    responseId: nonEmpty(env.CODETOUR_RESPONSE_ID),
    host: nonEmpty(env.CODETOUR_HOST) ?? observedHost,
  };
}

export interface CreationRecordInput {
  workspaceRoot: string;
  tourPath: string;
  tourTitle: string;
  kind: TourKind;
}

// Write one creation record. Returns the written file, or undefined when the
// journal is unavailable; the caller treats that as a diagnostic, never as a
// failure of the creation itself.
export async function recordCreation(
  input: CreationRecordInput,
  identity: CreationIdentity = creationIdentity()
): Promise<string | undefined> {
  const createdAt = new Date();
  const record: CreationRecord = {
    version: CREATION_RECORD_VERSION,
    workspace: input.workspaceRoot,
    tourPath: input.tourPath,
    tourTitle: input.tourTitle,
    kind: input.kind,
    at: createdAt.toISOString(),
    sessionId: identity.sessionId,
    responseId: identity.responseId,
    host: identity.host,
  };
  const directory = path.join(input.workspaceRoot, CREATIONS_DIRECTORY);
  // `<createdAtMs>-<pid>-<random>`: sortable by time, unique under concurrent
  // creations from the same process.
  const fileName = `${createdAt.getTime()}-${process.pid}-${randomBytes(4).toString("hex")}.json`;
  const target = path.join(directory, fileName);
  const temporary = path.join(directory, `.${fileName}.tmp`);
  try {
    await fs.mkdir(directory, { recursive: true });
    await fs.writeFile(temporary, `${JSON.stringify(record, null, 2)}\n`, "utf8");
    await fs.rename(temporary, target);
    return target;
  } catch {
    await fs.rm(temporary, { force: true }).catch(() => undefined);
    return undefined;
  }
}

